#!/usr/bin/env python3
#
# Visualization Vignettes
#
# prepare_machine.py
#
# Bring one machine to the point where the vignette suite can run.
#
# WHY THIS EXISTS
#
# Three of the suite's inputs are not in git. Two of them are generated by a
# tool rather than downloaded, and those two do NOT survive being copied
# between machines that run different ParaView versions:
#
#   data/                          fetched once, machine-independent
#   data/topologies/               generated, ParaView major.minor specific
#   ex11_state.pvsm                generated, ParaView major.minor specific
#   ex11_visit.session             generated, VisIt version specific
#   ex11_series.visit              generated, holds absolute paths
#
# data/topologies/ and the XML time series (data/varying_series_xml) are
# built with pvbatch but read by the VisIt suite too (ex09; ex05 and ex12).
# --tool VisIt cannot build them, so it checks that they exist and stops
# with the command that builds them, instead of letting ex05 fail mid-suite.
# --tests limits that check to the vignettes about to run.
#
# Until now that was four commands documented in four places -- a comment in
# each .sbat header, Testing/README.md, data/README.md and the runbook -- and
# nothing checked. Worse, getting it wrong is quiet: an AMR hierarchy written
# by ParaView 6.1.0 opens without complaint under 6.0.1, which then reads 216
# points where 6.1.0 wrote 842. No error. ex09 just reports different numbers
# and fails its numeric gate for a reason that looks like a regression.
#
# So: one idempotent command that does all of it, says what it did and what it
# skipped, and re-does only what is actually stale. The vignettes check the
# same provenance at run time and name this script when it does not match.
#
# USAGE
#
#   python3 Testing/prepare_machine.py                 # both tools, as found
#   python3 Testing/prepare_machine.py --tool ParaView
#   python3 Testing/prepare_machine.py --force         # regenerate regardless
#   python3 Testing/prepare_machine.py --check         # report only, change nothing
#
# It finds pvbatch and visit the same way run_tests.py does: $PARAVIEW_PATH and
# $VISIT_PATH first, then PATH. A tool that is not present is skipped with a
# note, not an error, so this is safe to run on a machine that has only one of
# them.
#
# Author: James Kress, <james@jameskress.com>
#
from __future__ import print_function

