def use_data_dir(path):
    """Check fixtures under `path` instead of the repository's data/.

    For test_suite.py --data-dir, whose vignettes read their datasets from
    there. Only the checks move: the generators always write into the
    repository's data/, so this is accepted with --check only.
    """
    global TOPOLOGY_DIR, TOPOLOGY_MANIFEST, TIME_SERIES_DIR
    global TIME_SERIES_MANIFEST, TIME_SERIES_SOURCE, LARGE_DATA_MARKERS
    global CHECKED_DATA_DIR
    data = os.path.abspath(path)
    CHECKED_DATA_DIR = data
    TOPOLOGY_DIR = os.path.join(data, "topologies")
    TOPOLOGY_MANIFEST = os.path.join(TOPOLOGY_DIR, "topologies_manifest.json")
    TIME_SERIES_DIR = os.path.join(data, "varying_series_xml")
    TIME_SERIES_MANIFEST = os.path.join(TIME_SERIES_DIR, "manifest.json")
    TIME_SERIES_SOURCE = os.path.join(data, "varying_data")
    LARGE_DATA_MARKERS = (
        os.path.join(data, "cyclone-chapala-2015-11-02_00-00-00-mb.vtm"),
        os.path.join(data, "currentRainfall.silo"),
    )


GREEN, YELLOW, RED, RESET = "\033[32m", "\033[33m", "\033[31m", "\033[0m"
if not sys.stdout.isatty():
    GREEN = YELLOW = RED = RESET = ""


def say(symbol, colour, message):
    print("{0}{1}{2} {3}".format(colour, symbol, RESET, message))
    sys.stdout.flush()


def ok(message):
    say("OK  ", GREEN, message)


def todo(message):
    say("MAKE", YELLOW, message)


def bad(message):
    say("FAIL", RED, message)


def skip(message):
    say("SKIP", YELLOW, message)


# ---------------------------------------------------------------------------
# Tool discovery -- same rules as run_tests.py
# ---------------------------------------------------------------------------
def find_executable(name, env_var):
    root = os.getenv(env_var)
    if root:
        candidate = os.path.join(root, name)
        if os.path.isfile(candidate) and os.access(candidate, os.X_OK):
            return candidate
    return shutil.which(name)


def paraview_version(pvbatch):
    """major.minor.patch of the pvbatch we are about to use, or None.

    Two ways, cheapest first.

    `--version` is a banner every build prints, needs no temp file and no
    import, and is the only one that worked on Shaheen's source build
    (/sw/vis2/.../paraview-buildMesa-6.1.0). That build does not define
    `paraview.__version__`, so the import probe alone returned nothing and
    this reported "unknown" -- while the generators, which fall back to
    GetParaViewVersion(), recorded "6.1.0" into their manifests. The two then
    disagreed and --check called a fixture stale seconds after building it.

    The import probe stays as the fallback, now with the same fallback chain
    the generators use, so the two can no longer reach different answers.
    """
    banner = _run_banner([pvbatch, "--version"])
    if banner:
        return banner

    probe = (
        "import sys, os\n"
        "version = ''\n"
        "try:\n"
        "    import paraview\n"
        "    version = getattr(paraview, '__version__', '') or ''\n"
        "except Exception:\n"
        "    pass\n"
        "if not version:\n"
        "    try:\n"
        "        from paraview.simple import GetParaViewVersion\n"
        "        version = '.'.join(str(p) for p in GetParaViewVersion())\n"
        "    except Exception:\n"
        "        pass\n"
        "sys.stdout.write(version)\n"
        "sys.stdout.flush()\n"
        "os._exit(0)\n"
    )
    return _run_probe(pvbatch, probe, ".py")


def _run_banner(cmd):
    """First version-shaped number from a `--version` style banner, or None.

    stdout and stderr are both read: which one a build uses for its banner is
    not something to depend on.
    """
    try:
        result = subprocess.run(
            cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=60
        )
    except Exception:  # noqa: BLE001 - a probe that fails is just "unknown"
        return None
    text = (result.stdout + result.stderr).decode("utf-8", "replace")
    match = re.search(r"\d+\.\d+(\.\d+)?", text)
    return match.group(0) if match else None


def visit_version(visit):
    probe = (
        "import sys, os\n"
        "sys.stdout.write(str(Version()))\n"
        "sys.stdout.flush()\n"
        "exit(0)\n"
    )
    return _run_probe(visit, probe, ".py", visit=True)


def _run_probe(executable, source, suffix, visit=False):
    import tempfile

    handle, path = tempfile.mkstemp(suffix=suffix)
    try:
        with os.fdopen(handle, "w") as script:
            script.write(source)
        cmd = (
            [executable, "-cli", "-nowin", "-noconfig", "-s", path]
            if visit
            else [executable, path]
        )
        result = subprocess.run(
            cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=180
        )
        text = result.stdout.decode("utf-8", "replace").strip()
        match = re.search(r"\d+\.\d+(\.\d+)?", text)
        return match.group(0) if match else None
    except Exception:  # noqa: BLE001 - a probe that fails is just "unknown"
        return None
    finally:
        try:
            os.unlink(path)
        except OSError:
            pass


def major_minor(version):
    if not version:
        return None
    parts = str(version).split(".")
    if len(parts) < 2:
        return None
    try:
        return (int(parts[0]), int(parts[1]))
    except ValueError:
        return None


# ---------------------------------------------------------------------------
# What each fixture says about itself
# ---------------------------------------------------------------------------
def topology_recorded_version():
    if not os.path.exists(TOPOLOGY_MANIFEST):
        return None
    try:
        with open(TOPOLOGY_MANIFEST, "r") as handle:
            document = json.load(handle)
    except (ValueError, OSError):
        return None
    return document.get("paraview_version") if isinstance(document, dict) else None


def pvsm_recorded_version(path):
    try:
        with open(path, "r") as handle:
            for _ in range(20):
                line = handle.readline()
                if not line:
                    break
                match = re.search(r'ServerManagerState[^>]*version="([^"]+)"', line)
                if match:
                    return match.group(1)
    except (OSError, IOError):
        pass
    return None


def run(cmd, cwd=None):
    print("    $ {0}".format(" ".join(cmd)))
    sys.stdout.flush()
    result = subprocess.run(cmd, cwd=cwd)
    return result.returncode == 0


# ---------------------------------------------------------------------------
# Steps
# ---------------------------------------------------------------------------
def step_large_data(args):
    """ex06's datasets. Machine-independent, so only presence is checked."""
    missing = [p for p in LARGE_DATA_MARKERS if not os.path.exists(p)]
    if not missing:
        ok("ex06 datasets present")
        return True

    todo(
        "ex06 datasets missing ({0})".format(
            ", ".join(os.path.basename(p) for p in missing)
        )
    )
    if args.check:
        return False
    print("    4.3 GB download. Skipping automatically; run it yourself if you")
    print("    intend to run ex06:")
    print("        cd data && ./fetchData.sh")
    return False


def step_topologies(args, pvbatch, pv_version):
    """data/topologies -- generated, and ParaView major.minor specific."""
    recorded = topology_recorded_version()
    present = os.path.exists(TOPOLOGY_MANIFEST)

    if present and not args.force:
        if recorded is None:
            todo("data/topologies exists but records no ParaView version")
        elif major_minor(recorded) == major_minor(pv_version):
            ok("data/topologies generated by ParaView {0}".format(recorded))
            return True
        elif major_minor(pv_version) is None:
            # Not knowing the running version is not evidence of staleness,
            # and treating it as such refused to start a run against fixtures
            # that had just been built by that very pvbatch.
            ok(
                "data/topologies generated by ParaView {0}; cannot read the "
                "running version to compare. Use --force after a module "
                "change.".format(recorded)
            )
            return True
        else:
            todo(
                "data/topologies generated by ParaView {0}, running {1} -- "
                "stale".format(recorded, pv_version)
            )
    elif not present:
        todo("data/topologies missing")
    else:
        todo("data/topologies -- regenerating (--force)")

    if args.check:
        return False
    return run([pvbatch, TOPOLOGY_GENERATOR], cwd=REPO)


def step_time_series(args, pvbatch):
    """data/varying_series_xml -- generated, and only as current as its source.

    Not version-locked: it is plain XML VTK that every build in this
    repository reads identically. It IS source-locked, so a count mismatch
    against data/varying_data means it is stale.
    """
    source_count = 0
    if os.path.isdir(TIME_SERIES_SOURCE):
        source_count = len(
            [n for n in os.listdir(TIME_SERIES_SOURCE) if n.lower().endswith(".vtk")]
        )
    if source_count == 0:
        skip("XML time series: source data/varying_data is absent")
        return True

    recorded = 0
    if os.path.exists(TIME_SERIES_MANIFEST):
        try:
            with open(TIME_SERIES_MANIFEST, "r") as handle:
                recorded = len(json.load(handle).get("timesteps", []))
        except (ValueError, OSError):
            recorded = 0

    if recorded == source_count and not args.force:
        ok("XML time series present ({0} timestep(s))".format(recorded))
        return True

    if recorded == 0:
        todo("XML time series missing")
    elif args.force:
        todo("XML time series -- regenerating (--force)")
    else:
        todo(
            "XML time series has {0} timestep(s), source has {1} -- "
            "stale".format(recorded, source_count)
        )

    if args.check:
        return False
    return run([pvbatch, TIME_SERIES_GENERATOR], cwd=REPO)


def checked(step, what):
    """Run a check; an exception inside it is a failed check, with its reason."""
    try:
        return step()
    except Exception as exc:  # noqa: BLE001 - any failure to check is a FAIL
        bad(
            "{0}: could not be checked ({1}: {2})".format(what, type(exc).__name__, exc)
        )
        return False


def step_time_series_for_visit():
    """The XML time series, as the VisIt suite needs it: present and current.

    Unlike step_time_series this cannot build it (no pvbatch), so it never
    regenerates and ignores --force, and it requires the series even when
    its source is absent: without the series ex05 and ex12 cannot run.
    """
    steps = []
    if os.path.exists(TIME_SERIES_MANIFEST):
        try:
            with open(TIME_SERIES_MANIFEST, "r") as handle:
                document = json.load(handle)
            steps = document.get("timesteps") if isinstance(document, dict) else None
        except (ValueError, OSError):
            steps = None
        # A malformed manifest counts as missing rather than raising, which
        # the suite's preflight would treat as "could not check".
        if not isinstance(steps, list) or not all(
            isinstance(step, dict)
            and isinstance(step.get("file"), str)
            and step["file"].strip()
            for step in steps
        ):
            steps = []
    recorded = len(steps)
    # The files ex05 and ex12 open: the .visit index, each timestep the
    # manifest lists, and each file the index itself names.
    wanted = [os.path.join(TIME_SERIES_DIR, "series.visit")]
    wanted += [os.path.join(TIME_SERIES_DIR, step["file"]) for step in steps]
    indexed = visit_index_files(wanted[0])
    missing = [
        os.path.relpath(path, TIME_SERIES_DIR)
        for path in wanted + (indexed or [])
        if not os.path.isfile(path)
    ]
    if recorded and indexed is None and "series.visit" not in missing:
        missing.append("readable series.visit")
    # VisIt reads the series through the index, so it must name exactly the
    # manifest's timesteps, in order; anything else is another series.
    if recorded and indexed is not None:
        listed = [
            os.path.normpath(os.path.relpath(p, TIME_SERIES_DIR)) for p in indexed
        ]
        expected = [os.path.normpath(step["file"]) for step in steps]
        if listed != expected:
            missing.append("series.visit matching the manifest")
    source_count = 0
    if os.path.isdir(TIME_SERIES_SOURCE):
        source_count = len(
            [n for n in os.listdir(TIME_SERIES_SOURCE) if n.lower().endswith(".vtk")]
        )
    build = (
        "the VisIt suite reads it (ex05, ex12) but it is built with pvbatch "
        "from the shipped data/varying_data: run `python3 "
        "Testing/prepare_machine.py --tool ParaView` with a ParaView module "
        "loaded" + where_to_build()
    )
    if recorded == 0:
        if os.path.exists(TIME_SERIES_MANIFEST):
            # A manifest is there but unusable; only --force makes ParaView
            # regenerate past it.
            bad(
                "XML time series manifest unusable: "
                + build.replace("--tool ParaView`", "--tool ParaView --force`")
            )
        else:
            bad("XML time series missing: " + build)
        return False
    if missing:
        # The manifest is intact, so only --force makes ParaView rebuild it.
        bad(
            "XML time series incomplete ({0} file(s) missing, first {1}): "
            "{2}".format(
                len(missing),
                missing[0] or "an unnamed timestep",
                build.replace("--tool ParaView`", "--tool ParaView --force`"),
            )
        )
        return False
    if source_count and recorded != source_count:
        bad(
            "XML time series has {0} timestep(s), source has {1} -- stale: "
            "{2}".format(recorded, source_count, build)
        )
        return False
    ok("XML time series present ({0} timestep(s))".format(recorded))
    return True


def step_topologies_for_visit():
    """data/topologies, as the VisIt suite needs it: present, any version.

    The ParaView major.minor lock is about ParaView reading what another
    ParaView wrote; VisIt only needs the files. They are built with pvbatch,
    which --tool VisIt does not have, so this only checks.
    """
    recorded = topology_recorded_version()
    missing = [
        name
        for name in VISIT_TOPOLOGY_FILES
        if not os.path.exists(os.path.join(TOPOLOGY_DIR, name))
    ]
    # The ragged .visit index names its blocks, which are separate files.
    index = os.path.join(TOPOLOGY_DIR, "ragged_multidomain.visit")
    blocks = visit_index_files(index)
    if blocks is None:
        if "ragged_multidomain.visit" not in missing:
            missing.append("readable ragged_multidomain.visit")
    else:
        missing += [
            os.path.relpath(path, TOPOLOGY_DIR)
            for path in blocks
            if not os.path.exists(path)
        ]
    if recorded and not missing:
        ok("data/topologies present (generated by ParaView {0})".format(recorded))
        return True
    if not recorded:
        what, force = "missing", ""
    else:
        # The manifest is intact, so only --force makes ParaView rebuild.
        what, force = "incomplete (no {0})".format(", ".join(missing)), " --force"
    bad(
        "data/topologies {0}: the VisIt suite reads it (ex09) but it is "
        "built with pvbatch: run `python3 Testing/prepare_machine.py --tool "
        "ParaView{1}` with a ParaView module loaded{2}".format(
            what, force, where_to_build()
        )
    )
    return False


def step_pv_state(args, pvbatch, pv_version):
    """ex11_state.pvsm -- generated, and version-locked by design."""
    present = os.path.exists(PV_STATE)
    recorded = pvsm_recorded_version(PV_STATE) if present else None

    if present and not args.force:
        if major_minor(recorded) == major_minor(pv_version):
            ok("ex11_state.pvsm written by ParaView {0}".format(recorded))
            return True
        if recorded and major_minor(pv_version) is None:
            # As in step_topologies: unreadable is not stale.
            ok(
                "ex11_state.pvsm written by ParaView {0}; cannot read the "
                "running version to compare. Use --force after a module "
                "change.".format(recorded)
            )
            return True
        todo(
            "ex11_state.pvsm written by ParaView {0}, running {1} -- "
            "stale".format(recorded or "an unrecorded version", pv_version)
        )
    elif not present:
        todo("ex11_state.pvsm missing")
    else:
        todo("ex11_state.pvsm -- regenerating (--force)")

    if args.check:
        return False
    return run([pvbatch, PV_STATE_GENERATOR], cwd=PV_STATE_DIR)


# session_recorded_version() for a session that exists but cannot be read.
SESSION_UNREADABLE = "unreadable"


def session_recorded_version(path):
    """The VisIt version a .session says wrote it, or None.

    It is the first <Field name="Version"> of the file, near the top. A file
    that is empty or does not end with the closing </Object> of a whole
    session was cut short, and is SESSION_UNREADABLE.
    """
    try:
        with open(path, "r") as handle:
            head = handle.read(4096)
            handle.seek(0, os.SEEK_END)
            size = handle.tell()
            handle.seek(max(0, size - 256))
            tail = handle.read()
    except (OSError, UnicodeDecodeError):
        return SESSION_UNREADABLE
    if not head.strip() or not tail.rstrip().endswith("</Object>"):
        return SESSION_UNREADABLE
    match = re.search(r'<Field name="Version" type="string">([^<]+)</Field>', head)
    return match.group(1).strip() if match else None


def step_visit_state(args, visit, visit_ver):
    """ex11_visit.session and ex11_series.visit -- generated, not portable.

    The session is version-locked to the VisIt that wrote it, and the .visit
    index beside it holds absolute paths into this machine's data directory.
    Neither is committed. The session records the VisIt version that wrote it
    near its top, so a session from another version (the default moved from
    3.4.2 to 3.5.0, say) is regenerated; --force regenerates regardless.
    Regenerate by hand after moving the checkout or the data directory.
    """
    missing = [
        os.path.basename(path)
        for path in (VISIT_STATE, VISIT_SERIES)
        if not os.path.exists(path)
    ]
    recorded = None if missing else session_recorded_version(VISIT_STATE)
    # Unreadable is stale whatever the version; an older session with no
    # recorded version is accepted as before.
    stale = recorded == SESSION_UNREADABLE or bool(
        recorded and visit_ver and visit_ver != "unknown" and recorded != visit_ver
    )

    if not missing and not stale and not args.force:
        ok(
            "ex11_visit.session ({0}) and ex11_series.visit present (regenerate "
            "with --force after a move)".format(recorded or "version unrecorded")
        )
        return True

    if missing:
        reason = "missing: " + ", ".join(missing)
    elif recorded == SESSION_UNREADABLE:
        reason = "ex11_visit.session cannot be read -- stale"
    elif stale:
        reason = "written by VisIt {0}, running {1} -- stale".format(
            recorded, visit_ver
        )
    else:
        reason = "-- regenerating (--force)"
    todo("ex11 VisIt fixtures {0}".format(reason))
    if args.check:
        return False

    # --force (or a stale session) means "rebuild these", so clear them first. Otherwise the
    # presence check below would pass on the old files if the generator
    # failed, and report a rebuild that never happened.
    if args.force or stale:
        for path in (VISIT_STATE, VISIT_SERIES):
            if os.path.exists(path):
                os.remove(path)

    run(
        [visit, "-cli", "-nowin", "-noconfig", "-s", VISIT_STATE_GENERATOR],
        cwd=VISIT_STATE_DIR,
    )

    # VisIt's launcher exits 250 after a clean shutdown -- see section 4b.1
    # of LOCAL_VALIDATION.md -- so its return code says nothing about whether
    # the generator worked. Taking it at face value here made a successful
    # run report one outstanding item, and `set -e` then killed the whole
    # VisIt CI job before a single vignette ran. The two files it was asked
    # to write are the only honest answer.
    still_missing = [
        os.path.basename(path)
        for path in (VISIT_STATE, VISIT_SERIES)
        if not os.path.exists(path)
    ]
    if still_missing:
        bad("ex11 VisIt fixtures still missing: " + ", ".join(still_missing))
        return False

    ok("ex11_visit.session and ex11_series.visit written")
    return True


# ---------------------------------------------------------------------------
def main(argv=None):
    parser = argparse.ArgumentParser(
        description="Generate the machine-specific fixtures the vignette "
        "suite needs. Idempotent: only what is missing or stale is rebuilt.",
        formatter_class=argparse.ArgumentDefaultsHelpFormatter,
    )
    parser.add_argument(
        "--tool",
        choices=("ParaView", "VisIt", "both"),
        default="both",
        help="Prepare for one tool or both. A tool that is not installed is "
        "skipped either way.",
    )
    parser.add_argument(
        "--tests",
        type=int,
        nargs="+",
        help="The vignette numbers about to run. With --tool VisIt, the "
        "pvbatch-built fixtures are required only when ex05, ex09 or ex12 is "
        "among them; without --tests, every vignette is assumed.",
    )
    parser.add_argument(
        "--skip-data-checks",
        action="store_true",
        help="With --tool VisIt: generate the VisIt state only, and leave the "
        "data fixtures (topologies, XML time series) to test_suite.py's "
        "preflight, which checks them with the run's own --data-dir and "
        "test selection. The batch scripts use this.",
    )
    parser.add_argument(
        "--data-dir",
        help="With --check: look for the data fixtures here instead of the "
        "repository's data/ (test_suite.py --data-dir passes its own).",
    )
    parser.add_argument(
        "--force",
        action="store_true",
        help="Regenerate everything, even what looks current.",
    )
    parser.add_argument(
        "--check",
        action="store_true",
        help="Report what would be done and change nothing. Exits 0 when "
        "ready, 1 when a generated fixture is missing or stale, and 3 when "
        "only ex06's large download is absent. Usable as a preflight.",
    )
    args = parser.parse_args(argv)
    if args.data_dir:
        if not args.check:
            parser.error(
                "--data-dir is accepted with --check only: the generators "
                "write into the repository's data/"
            )
        use_data_dir(args.data_dir)

    print("Repository : {0}".format(REPO))
    print("")

    outstanding = 0
    # Absent large data is a DIFFERENT kind of not-ready from a stale
    # fixture. A stale fixture is a correctness trap: it opens, it reads the
    # wrong thing, and the failure arrives later disguised as a regression.
    # A missing 4.3 GB download is just a download somebody has not done,
    # and it should not stop the other twelve vignettes from running or
    # block CI, which has no business fetching it.
    data_missing = 0

    if args.tool in ("ParaView", "both"):
        pvbatch = find_executable("pvbatch", "PARAVIEW_PATH")
        if not pvbatch:
            skip("pvbatch not found (set $PARAVIEW_PATH or load the module)")
        else:
            pv_version = paraview_version(pvbatch) or "unknown"
            print("ParaView   : {0}  ({1})".format(pv_version, pvbatch))
            if not step_topologies(args, pvbatch, pv_version):
                outstanding += 1
            if not step_pv_state(args, pvbatch, pv_version):
                outstanding += 1
            if not step_time_series(args, pvbatch):
                outstanding += 1
        print("")

    if args.tool in ("VisIt", "both"):
        visit = find_executable("visit", "VISIT_PATH")
        if not visit:
            skip("visit not found (set $VISIT_PATH or load the module)")
        else:
            visit_ver = visit_version(visit) or "unknown"
            print("VisIt      : {0}  ({1})".format(visit_ver, visit))
            if not step_visit_state(args, visit, visit_ver):
                outstanding += 1
            # Fixtures the VisIt suite reads but only pvbatch can build, and
            # only for the vignettes that read them (ex09; ex05 and ex12), so
            # a run that selects none of them (CI, which has no ParaView) is
            # not refused.
            wanted = set(args.tests) if args.tests else None
            if args.skip_data_checks:
                wanted = set()
            # These run even after the ParaView step: it trusts its manifests
            # (and skips the time series when its source is absent), while
            # these check the files VisIt opens.
            # A check that raises (an unlistable directory, say) must fail,
            # not escape: the suite's preflight treats an exception as "could
            # not check" and starts anyway.
            if wanted is None or 9 in wanted:
                if not checked(step_topologies_for_visit, "data/topologies"):
                    outstanding += 1
            if wanted is None or wanted & {5, 12}:
                if not checked(step_time_series_for_visit, "XML time series"):
                    outstanding += 1
        print("")

    if not step_large_data(args):
        data_missing = 1

    print("")
    if outstanding == 0 and data_missing == 0:
        ok("this machine is ready")
        return 0

    if outstanding == 0:
        skip("this machine is ready except for ex06's datasets (see above)")
        if not args.check:
            # Generate mode's contract is "build what you can", and it did.
            # The 4.3 GB download is not something it builds; it deliberately
            # refuses to start it. Reporting that as a non-zero exit made
            # `set -e` kill both CI jobs before a single vignette ran, which
            # is a worse outcome than the thing it was warning about.
            return 0
        # --check is a status query, so the code carries the answer: 3 means
        # ready except for ex06. test_suite.py's preflight treats it as a
        # warning, and a caller that genuinely needs ex06 can test for it.
        return 3

    if args.check:
        bad(
            "{0} generated fixture(s) missing or stale -- re-run without "
            "--check".format(outstanding)
        )
        return 1

    bad("{0} item(s) still outstanding (see above)".format(outstanding))
    return 1


if __name__ == "__main__":
    sys.exit(main())
